# Shared helpers for launchers that hydrate env from the workstation loader
# (generated by scripts/bootstrap-windows-secrets.py). Dot-source this file.
# Fail closed: a null/empty/missing loader or a failed/partial hydration throws.
# Messages name variables and paths only — never values (TASK-614).

function Resolve-PlxLoaderPath {
  param(
    [string]$LoaderPath,
    [string]$HomeDir = $HOME,
    [string]$FileName = '.secrets-env.staging.ps1'
  )
  # Order: explicit param, then PLX_SECRETS_LOADER env override, then $HOME default.
  if (-not [string]::IsNullOrWhiteSpace($LoaderPath)) { return $LoaderPath }
  if (-not [string]::IsNullOrWhiteSpace($env:PLX_SECRETS_LOADER)) { return $env:PLX_SECRETS_LOADER }
  if ([string]::IsNullOrWhiteSpace($HomeDir)) {
    throw 'cannot resolve secrets loader path: no -LoaderPath, PLX_SECRETS_LOADER is unset and $HOME is empty'
  }
  return (Join-Path $HomeDir $FileName)
}

function Import-PlxSecretsLoader {
  param(
    [string]$LoaderPath,
    [string[]]$RequiredEnv = @('MC_MCP_API_KEY')
  )
  $path = Resolve-PlxLoaderPath -LoaderPath $LoaderPath
  if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
    throw "secrets loader not found at $path — run: python scripts/bootstrap-windows-secrets.py"
  }
  # Clear any stale marker so only this load can report success.
  Remove-Variable -Name PlxSecretsLoaderStatus, PlxSecretsLoaderMissing -Scope Global -ErrorAction SilentlyContinue
  try {
    . $path
  } catch {
    $missing = [string]$global:PlxSecretsLoaderMissing
    $detail = if ($missing) { "missing: $missing" } else { $_.Exception.GetType().Name }
    throw "secrets loader failed at $path ($detail) — fix AWS credentials and re-run: python scripts/bootstrap-windows-secrets.py"
  }
  if ($global:PlxSecretsLoaderStatus -ne 'ok') {
    throw "secrets loader at $path did not report a complete hydration (status marker absent or not ok) — regenerate it: python scripts/bootstrap-windows-secrets.py"
  }
  $empty = @($RequiredEnv | Where-Object { [string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($_)) })
  if ($empty.Count -gt 0) {
    throw "secrets loader at $path left required env empty: $($empty -join ', ')"
  }
}
